package com.learn.hub.reactive;

import java.time.Duration;
import org.springframework.http.MediaType;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.reactive.function.client.WebClient;
import reactor.core.publisher.Flux;

@RestController
@RequestMapping("/api/v1/reactive/topics")
public class ReactiveTopicController {

    private final WebClient contentClient;

    public ReactiveTopicController(WebClient.Builder builder) {
        this.contentClient = builder.baseUrl("http://content-service:8080").build();
    }

    @GetMapping
    public Flux<TopicSummary> list() {
        return contentClient.get().uri("/api/v1/topics")
                .retrieve()
                .bodyToFlux(TopicSummary.class)
                .timeout(Duration.ofSeconds(2))
                .onErrorResume(error -> Flux.just(TopicSummary.fallback()));
    }

    @GetMapping(path = "/{slug}", produces = MediaType.TEXT_EVENT_STREAM_VALUE)
    public Flux<String> stream(@PathVariable String slug) {
        return contentClient.get().uri("/api/v1/topics/{slug}", slug)
                .retrieve()
                .bodyToFlux(String.class)
                .onErrorResume(error -> Flux.empty());
    }

    public record TopicSummary(String slug, String title) {
        public static TopicSummary fallback() {
            return new TopicSummary("fallback", "内容服务暂不可用");
        }
    }
}

package com.learn.hub.reactive;

import org.springframework.data.r2dbc.repository.Query;
import org.springframework.data.r2dbc.repository.R2dbcRepository;
import org.springframework.stereotype.Repository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import reactor.core.publisher.Flux;
import reactor.core.publisher.Mono;

@Repository
interface TopicRepository extends R2dbcRepository<TopicEntity, Long> {

    @Query("select id, slug, title, category from topic "
            + "where category = :category order by id limit :size offset :offset")
    Flux<TopicEntity> pageBy(String category, int size, long offset);
}

@Service
public class TopicQueryService {

    private final TopicRepository repository;

    public TopicQueryService(TopicRepository repository) {
        this.repository = repository;
    }

    public Flux<TopicEntity> page(String category, int page, int size) {
        return repository.pageBy(category, size, (long) page * size)
                .limitRate(size);
    }

    @Transactional
    public Mono<TopicEntity> rename(Long id, String title) {
        return repository.findById(id)
                .switchIfEmpty(Mono.error(new IllegalArgumentException("topic not found")))
                .flatMap(topic -> repository.save(topic.withTitle(title)));
    }
}

package com.learn.hub.reactive;

import java.time.Duration;
import org.junit.jupiter.api.Test;
import reactor.core.publisher.Flux;
import reactor.core.publisher.Mono;
import reactor.test.StepVerifier;
import reactor.util.context.Context;

class TopicPipelineTest {

    @Test
    void filterThenMap() {
        Flux<String> pipeline = Flux.just("spring-core", "data", "spring-core")
                .filter("spring-core"::equals)
                .map(String::toUpperCase);

        StepVerifier.create(pipeline)
                .expectNext("SPRING-CORE", "SPRING-CORE")
                .verifyComplete();
    }

    @Test
    void timeoutFallsBackWithTraceId() {
        Mono<String> pipeline = Mono.<String>never()
                .timeout(Duration.ofMillis(50))
                .onErrorResume(error -> Mono.deferContextual(ctx ->
                        Mono.just("fallback:" + ctx.get("traceId"))))
                .contextWrite(Context.of("traceId", "t-1"));

        StepVerifier.create(pipeline)
                .expectNext("fallback:t-1")
                .verifyComplete();
    }
}
